# Code generated by Claude
"""
Tests of the arm and gripper target modes of src/control_loop.py (cfg["target_mode"]) and of the per-source command rate ("hz").

    MUJOCO_GL=egl python experiments/target_mode_test.py

Each case runs the loop headless on the chemistry-lab scene with a scripted source, records it (src/run_record.py: the ctrl of every physics step) and
reads the ctrl of left joint 3 back from the recording.
1. "interpolate", source at 30 Hz: a command at tick t0 moves the ctrl linearly over the 25 physics steps (5 ticks) of the source's period, reaching the new
   target on the last of them, from the value it had before.
2. "hold", same source: the ctrl steps to the target on the first physics step of the tick and stays.
3. "interpolate", source at 150 Hz (the tick rate, no "hz"): the ramp is the 5 physics steps of one tick.
4. a second command in the middle of a ramp restarts the ramp from the current ctrl value.
5. the gripper is interpolated too (same ramp as the arm), and the pedestal and the neck are not (their ctrl is the target at once).
6. the replay of a recording with 30 Hz ramps is bit-identical.
7. src/sequential_policy.py: a stage with "hz" 30 is stepped only on every 5th tick and the policy's hz() reports it.
"""

import os
import shutil
import sys
import tempfile
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.control_loop import run_loop  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.run_record import load_recording  # noqa: E402
from src.sequential_policy import make_sequential_policy  # noqa: E402
from src.simulator import RobotSimulator  # noqa: E402

SCENE = "models/scenes/chemistry_lab_combined.xml"
SPAWN = [-1.0, 3.5, 0.22]
STEPS = 5                       # physics steps per tick
results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


_sim = {}


def run(script_sources, mode, frames, out, owners="script"):
    """Runs `frames` ticks with the given sources and target mode, recording to `out`; returns (recording, model).

    One model is built and reused (a model with cameras takes about 1.4 GB of memory); the data is reset for each run. `owners` is the
    source name, or tuple of names, that owns every route.
    """
    if "sim" not in _sim:
        _sim["sim"] = RobotSimulator(model_path=str(PROJECT_ROOT / SCENE), cameras=robot_specs.CAMERA_SPECS, pedestal_lift=robot_specs.PEDESTAL_SPECS)
    model, data = _sim["sim"].model, _sim["sim"].data
    mujoco.mj_resetData(model, data)
    routes = {k: owners for k in ("base", "pedestal", "arms.left", "arms.right", "gripper.left", "gripper.right", "neck")}
    cfg = {"spawn_pos": SPAWN, "cameras": False, "target_mode": mode, "routes": routes, "bench_frames": frames, "record_run": str(out),
           "record_meta": {"model": {"kind": "scene", "scene": SCENE}}}
    run_loop(model, data, script_sources, cfg, viewer=None)
    return load_recording(out), model


def scripted(events, hz=None):
    """A source that gives events[tick] (a command dict) on that tick; `hz` is its command rate (None: the tick rate)."""
    def step(obs):
        return events.get(obs["tick"])
    src = {"name": "script", "step": step}
    if hz is not None:
        src["hz"] = hz
    return src


def left_joint3(model):
    return model.actuator("left_joint3_ctrl").id


def ramp_case(tmp):
    j3 = None
    base_targets = [0.0, 0.5, 0.2]                       # the ctrl starts at the settled value (0, or the capture): use the first command as the reference
    events = {20: {"mode": "arms", "arm_targets": {"left": [0, 0, base_targets[1], 0, 0, 0, 0]}},
              45: {"mode": "arms", "arm_targets": {"left": [0, 0, base_targets[2], 0, 0, 0, 0]}}}

    print("\n1. interpolate, source at 30 Hz: a linear ramp over 25 physics steps")
    rec, model = run({"script": scripted(events, hz=30)}, "interpolate", 80, tmp / "i30")
    j3 = left_joint3(model)
    c = rec["ctrl"][:, :, j3].reshape(-1)                # one value per physics step
    s0 = 20 * STEPS
    before = c[s0 - 1]
    T1 = base_targets[1]
    expect = before + (T1 - before) * (np.arange(1, 26) / 25.0)
    check("the ctrl was constant before the command", np.ptp(c[s0 - 40:s0]) < 1e-12, f"{c[s0 - 1]:.6f}")
    check("the ctrl ramps linearly from its old value to the target over 25 steps", np.allclose(c[s0:s0 + 25], expect, atol=1e-12, rtol=0), f"max error {np.abs(c[s0:s0 + 25] - expect).max():.2e}")
    check("the ctrl is exactly the target on the last step of the period and after", np.all(c[s0 + 24:45 * STEPS] == T1))
    s1 = 45 * STEPS
    exp2 = T1 + (base_targets[2] - T1) * (np.arange(1, 26) / 25.0)
    check("the second command ramps from the first target", np.allclose(c[s1:s1 + 25], exp2, atol=1e-12, rtol=0))
    check("the applied target (what policies see) is the final one at once: the recorded state hashes exist for every tick", len(rec["hashes"]) == len(rec["ctrl"]))
    check("the recording holds the ctrl of every physics step, shape (ticks, 5, nu)", rec["ctrl"].shape[1:] == (STEPS, model.nu), str(rec["ctrl"].shape))

    print("\n2. hold, source at 30 Hz: a step on the first physics step")
    rec, model = run({"script": scripted(events, hz=30)}, "hold", 80, tmp / "h30")
    c = rec["ctrl"][:, :, j3].reshape(-1)
    check("the ctrl steps to the target on the first physics step of the tick", c[s0 - 1] != T1 and np.all(c[s0:s1] == T1), f"{c[s0 - 1]:.4f} -> {c[s0]:.4f}")

    print("\n3. interpolate, source at the tick rate (150 Hz): a ramp over the 5 physics steps of the tick")
    rec, model = run({"script": scripted(events)}, "interpolate", 80, tmp / "i150")
    c = rec["ctrl"][:, :, j3].reshape(-1)
    before = c[s0 - 1]
    check("a 5-step ramp", np.allclose(c[s0:s0 + 5], before + (T1 - before) * np.arange(1, 6) / 5.0, atol=1e-12, rtol=0) and np.all(c[s0 + 4:s1] == T1))

    print("\n4. a command in the middle of a ramp restarts it from the current value")
    ev = {20: {"mode": "arms", "arm_targets": {"left": [0, 0, 0.5, 0, 0, 0, 0]}}}
    extra = {"mode": "arms", "arm_targets": {"left": [0, 0, 0.1, 0, 0, 0, 0]}}
    other = {"name": "other", "step": lambda obs: extra if obs["tick"] == 23 else None}      # at the tick rate (5-step ramp), 3 ticks = 15 steps into the 25-step ramp
    rec, model = run({"script": scripted(ev, hz=30), "other": other}, "interpolate", 60, tmp / "mid", owners=("script", "other"))
    c = rec["ctrl"][:, :, j3].reshape(-1)
    start = c[s0 - 1]
    at23 = c[23 * STEPS - 1]
    check("the first ramp was 15 of 25 steps along when the second command came", abs(at23 - (start + (0.5 - start) * 15 / 25)) < 1e-12, f"{at23:.4f}")
    check("the second ramp (5 steps) starts from that value and ends at its target", np.allclose(c[23 * STEPS:23 * STEPS + 5], at23 + (0.1 - at23) * np.arange(1, 6) / 5.0, atol=1e-12, rtol=0) and c[23 * STEPS + 4] == 0.1)

    print("\n5. the gripper is interpolated; the pedestal and the neck are not")
    gr = {20: {"mode": "arms", "gripper": {"left": 0.02}}, 30: {"mode": "pedestal", "height": -0.05}, 40: {"mode": "neck", "neck_targets": {"shoulder_pan": 0.02}}}
    rec, model = run({"script": scripted(gr, hz=30)}, "interpolate", 80, tmp / "misc")
    f1 = model.actuator("left_finger1_ctrl").id
    cg = rec["ctrl"][:, :, f1].reshape(-1)
    g0 = cg[s0 - 1]
    check("the gripper ctrl ramps over 25 steps", np.allclose(cg[s0:s0 + 25], g0 + (0.02 - g0) * np.arange(1, 26) / 25.0, atol=1e-12, rtol=0))
    cp = rec["ctrl"][:, :, model.actuator(robot_specs.PEDESTAL_SPECS["actuator_name"]).id].reshape(-1)
    check("the pedestal ctrl is the target on the first step", cp[30 * STEPS] == -0.05 and cp[30 * STEPS - 1] != -0.05)
    from src.neck import neck_ids
    nk = neck_ids(model, robot_specs.NECK_SPECS)
    cn = rec["ctrl"][:, :, nk["act"][nk["names"].index("shoulder_pan")]].reshape(-1)
    slew = robot_specs.NECK_SPECS["max_speed"] / 150.0                      # the loop moves the neck target at most this much per tick
    d = np.abs(np.diff(cn[40 * STEPS - 1:46 * STEPS]))
    check("the neck ctrl is the loop's slewed target: it changes only at tick starts, by the slew step (no ramp over the source's period)",
          np.isclose(cn[40 * STEPS] - cn[40 * STEPS - 1], 0.02 - cn[40 * STEPS - 1] if abs(0.02 - cn[40 * STEPS - 1]) <= slew else slew) and np.count_nonzero(d[1:5]) == 0, f"first step {cn[40 * STEPS] - cn[40 * STEPS - 1]:+.5f} (slew {slew:.5f})")

    print("\n6. the replay of a recording with 30 Hz ramps is bit-identical")
    _sim.clear()                                          # the replay builds its own model
    import gc
    gc.collect()
    rep = replay_run(tmp / "i30", video="none", quiet=True)
    check("bit-identical replay", rep["ok"], f"{rep['ticks']} ticks, mismatch {rep['mismatch']}")


def gating_case():
    print("\n7. a stage with hz 30 is stepped on every 5th tick")
    calls = []
    stage = {"name": "S", "step": lambda obs: calls.append(obs["tick"]) or None, "hz": 30.0}
    pol = make_sequential_policy([stage])
    for t in range(20):
        pol["step"]({"tick": t, "timestep": 1 / 750, "steps_per_frame": 5})
    check("stepped on ticks 0, 5, 10, 15", calls == [0, 5, 10, 15], str(calls))
    check("the policy reports the stage's rate", pol["hz"]() == 30.0)
    free = make_sequential_policy([{"name": "F", "step": lambda obs: None}])
    free["step"]({"tick": 1, "timestep": 1 / 750, "steps_per_frame": 5})
    check("a stage without hz gives None (the loop uses its tick)", free["hz"]() is None)


if __name__ == "__main__":
    tmp = Path(tempfile.mkdtemp(prefix="target_mode_"))
    try:
        ramp_case(tmp)
        gating_case()
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    sys.exit(0 if all(results) else 1)
